#[allow(non_snake_case)]
pub(crate) fn bInpInchiComponentExists(
    heap: &SourceHeap,
    pOneInput: &InpInChI,
    iInChI: i32,
    bMobileH: i32,
    k: i32,
) -> Result<i32, SourceHeapError> {
    // BEGIN INCHI C FUNCTION: third_party/InChI/INCHI-1-SRC/INCHI_BASE/src/ichiread.c:1800 bInpInchiComponentExists
    // INCHI✔❌: complete source frame follows verbatim.
    /*
    int bInpInchiComponentExists(InpInChI* pOneInput,
        int       iInChI,
        int       bMobileH,
        int       k)
    {
        if ((INCHI_BAS != iInChI && iInChI != INCHI_REC) ||
            (TAUT_NON != bMobileH && TAUT_YES != bMobileH) || k < 0) /* djb-rwth: addressing LLVM warnings */
        {
            return 0;
        }

        return (k < pOneInput->nNumComponents[iInChI][bMobileH] &&
            pOneInput->pInpInChI[iInChI][bMobileH] &&
            pOneInput->pInpInChI[iInChI][bMobileH][k].nNumberOfAtoms > 0 &&
            !pOneInput->pInpInChI[iInChI][bMobileH][k].bDeleted);
    }
    */
    // END INCHI C FUNCTION: bInpInchiComponentExists
    // BEGIN INCHI ACTIVE MACRO CONFIGURATION: bInpInchiComponentExists
    // INCHI✔❌: READ_INCHI_STRING=1 includes this production helper.
    // INCHI✔❌: COMPILE_ANSI_ONLY and TARGET_API_LIB do not alter this function body.
    // END INCHI ACTIVE MACRO CONFIGURATION: bInpInchiComponentExists

    if (iInChI != INCHI_BAS as i32 && iInChI != INCHI_REC as i32)
        || (bMobileH != TAUT_NON as i32 && bMobileH != TAUT_YES as i32)
        || k < 0
    {
        return Ok(0);
    }
    let representation = iInChI as usize;
    let mobile_h = bMobileH as usize;
    if k >= pOneInput.nNumComponents[representation][mobile_h] {
        return Ok(0);
    }
    let components = pOneInput.pInpInChI[representation][mobile_h];
    if components.is_null() {
        return Ok(0);
    }
    let component = heap
        .slice(components.offset(i64::from(k))?.as_const())?
        .first()
        .ok_or(SourceHeapError::PointerOutOfBounds)?;
    Ok(i32::from(
        component.nNumberOfAtoms > 0 && component.bDeleted == 0,
    ))
}

