    // INCHI✔️❌:         {/* inchi_ios_eprint( pOut, "InChICreationError!\n"); *//* emit err string */
    // INCHI✔️❌:             if (ip->bINChIOutputOptions & INCHI_OUT_STDINCHI)
    // INCHI✔️❌:             {
