    fn calloc_or_null<T: Clone + Default + 'static>(
        heap: &mut SourceHeap,
        count: u64,
    ) -> Result<SourceMutPointer<T>, SourceHeapError> {
        match inchi_calloc::<T>(heap, count, std::mem::size_of::<T>() as u64) {
            Ok(pointer) => Ok(pointer),
            Err(SourceHeapError::AllocationFailed | SourceHeapError::AllocationSizeOverflow | SourceHeapError::AllocationElementCountOutOfRange) => Ok(SourceMutPointer::null()),
            Err(error) => Err(error),
        }
    }

    fn position(
        base: SourceConstPointer<i8>,
        pointer: SourceConstPointer<i8>,
    ) -> Result<usize, SourceHeapError> {
        usize::try_from(pointer.as_mut().difference(base.as_mut())?)
            .map_err(|_| SourceHeapError::PointerDifferenceOverflow)
    }

