        let mut identity_marks = [9_i32; 5];
        assert_eq!(
            extract_stereo_info_from_inchi_string(
                &mut heap,
                input,
                3,
                &[0, 1, 2, 3],
                &mut identity_marks,
            ),
            Ok(0)
        );
        assert_eq!(identity_marks[0], 0);
        assert_eq!(identity_marks[1], 0);
        assert_ne!(identity_marks[2], 0);
        assert_eq!(identity_marks[3], 0);
        assert_eq!(identity_marks[4], 9);
        let parity = identity_marks[2];

        let remapped_input = c_string(&mut heap, LACTIC);
        let mut remapped_marks = [7_i32; 5];
        assert_eq!(
            extract_stereo_info_from_inchi_string(
                &mut heap,
                remapped_input,
                3,
                &[0, 3, 1, 2],
                &mut remapped_marks,
            ),
            Ok(0)
        );
        assert_eq!(remapped_marks, [0, parity, 0, 0, 7]);

        let methane = c_string(&mut heap, "InChI=1S/CH4/h1H4");
        let mut no_stereo = [5_i32; 3];
        assert_eq!(
            extract_stereo_info_from_inchi_string(&mut heap, methane, 1, &[0, 1], &mut no_stereo,),
            Ok(0)
        );
        assert_eq!(no_stereo, [0, 0, 5]);

        let malformed = c_string(&mut heap, "InChI=1S/CH4/i\n");
        let mut malformed_marks = [6_i32; 3];
        assert_eq!(
            extract_stereo_info_from_inchi_string(
                &mut heap,
                malformed,
                1,
                &[0, 1],
                &mut malformed_marks,
            ),
            Ok(_IS_ERROR as i32)
        );
