    #[test]
    fn source_port__ichiread__parsesegmentperm__line_5663() {
        use crate::source_types::local_ichiread::{
            tagInChI_STATE_IST_FIXED_H_ISO_PERMUTATION, tagInChI_STATE_IST_FIXED_H_PERMUTATION,
        };

        fn parse(
            heap: &mut SourceHeap,
            text: &str,
            mobile: i32,
            layers: &[SourceMutPointer<INChI>; TAUT_NUM as usize],
            counts: &[i32; TAUT_NUM as usize],
            state: u32,
            abc: &mut i32,
        ) -> Result<i32, SourceHeapError> {
            let input = c_string(heap, text);
            ParseSegmentPerm(heap, input, mobile, layers, counts, state, abc)
        }

        fn components(heap: &mut SourceHeap) -> SourceMutPointer<INChI> {
            let atom_1 = heap.allocate_model_storage(vec![11_u8]).unwrap();
            let atom_2 = heap.allocate_model_storage(vec![12_u8]).unwrap();
            let atom_3 = heap.allocate_model_storage(vec![13_u8]).unwrap();
            heap.allocate_model_storage(vec![
                INChI {
                    nErrorCode: 101,
                    nTotalCharge: 1,
                    nNumberOfAtoms: 11,
                    nAtom: atom_1,
                    nLink: 1001,
                    ..INChI::default()
                },
                INChI {
                    nErrorCode: 202,
                    nTotalCharge: 2,
                    nNumberOfAtoms: 22,
                    nAtom: atom_2,
                    nLink: 2002,
                    ..INChI::default()
                },
                INChI {
                    nErrorCode: 303,
                    nTotalCharge: 3,
                    nNumberOfAtoms: 33,
                    nAtom: atom_3,
                    nLink: 3003,
                    ..INChI::default()
                },
            ])
            .unwrap()
        }

        fn values(
            heap: &SourceHeap,
            pointer: SourceMutPointer<INChI>,
        ) -> Vec<(i32, i32, i32, SourceMutPointer<u8>)> {
            heap.slice(pointer.as_const())
                .unwrap()
                .iter()
                .map(|value| {
                    (
                        value.nErrorCode,
                        value.nTotalCharge,
                        value.nLink,
                        value.nAtom,
                    )
                })
                .collect()
        }

        let fixed_state = tagInChI_STATE_IST_FIXED_H_PERMUTATION as u32;
        let iso_state = tagInChI_STATE_IST_FIXED_H_ISO_PERMUTATION as u32;
        let counts = [3, 0];
        let mut heap = SourceHeap::default();
        let null_layers = [SourceMutPointer::null(); TAUT_NUM as usize];
        let mut abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "x(1,2)",
                TAUT_NON as i32,
                &null_layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(0)
        );
        assert_eq!(abc, -1);
        assert_eq!(
            parse(
                &mut heap,
                "o(1,2)",
                TAUT_NON as i32,
                &null_layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(RI_ERR_ALLOC)
        );

        let fixed = components(&mut heap);
        let mobile = components(&mut heap);
        let layers = [fixed, mobile];
        assert_eq!(
            parse(
                &mut heap,
                "o(1,2)",
                TAUT_YES as i32,
                &layers,
                &[3, 3],
                fixed_state,
                &mut abc,
            ),
            Ok(RI_ERR_PROGR)
        );
        assert_eq!(
            parse(
                &mut heap,
                "o(1,2)",
                TAUT_NON as i32,
                &layers,
                &counts,
                u32::MAX,
                &mut abc,
            ),
            Ok(RI_ERR_PROGR)
        );
        assert_eq!(
            parse(
                &mut heap,
                "o(1,2);",
                TAUT_NON as i32,
                &layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(RI_ERR_SYNTAX)
        );
        assert_eq!(
            parse(
                &mut heap,
                "o",
                TAUT_NON as i32,
                &layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(1)
        );

        let decimal = components(&mut heap);
        let decimal_layers = [decimal, SourceMutPointer::null()];
        let before = values(&heap, decimal);
        abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "o(1,2,3)",
                TAUT_NON as i32,
                &decimal_layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(1)
        );
        assert_eq!(abc, 0);
        assert_eq!(
            values(&heap, decimal),
            vec![before[1], before[2], before[0]]
        );

        let sequential = components(&mut heap);
        let sequential_layers = [sequential, SourceMutPointer::null()];
        let before = values(&heap, sequential);
        abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "o(1,2)(2,3)",
                TAUT_NON as i32,
                &sequential_layers,
                &counts,
                iso_state,
                &mut abc,
            ),
            Ok(1)
        );
        assert_eq!(
            values(&heap, sequential),
            vec![before[1], before[2], before[0]]
        );

        let compressed = components(&mut heap);
        let compressed_layers = [compressed, SourceMutPointer::null()];
        let before = values(&heap, compressed);
        abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "o(ABC)",
                TAUT_NON as i32,
                &compressed_layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(1)
        );
        assert_eq!(abc, 1);
        assert_eq!(
            values(&heap, compressed),
            vec![before[1], before[2], before[0]]
        );

        for (text, forced_abc) in [
            ("o()", -1),
            ("o(1)", -1),
            ("o(0,1)", 0),
            ("o(1,4)", 0),
            ("o(-1,2)", 0),
            ("o(1 2)", 0),
            ("o(1,2", 0),
            ("oX", 0),
            ("o(1,2)", 1),
            ("o(AB)", 0),
            ("o(ab)", 1),
        ] {
            let pointer = components(&mut heap);
            let test_layers = [pointer, SourceMutPointer::null()];
            let mut mode = forced_abc;
            assert_eq!(
                parse(
                    &mut heap,
                    text,
                    TAUT_NON as i32,
                    &test_layers,
                    &counts,
                    fixed_state,
                    &mut mode,
                ),
                Ok(RI_ERR_SYNTAX),
                "{text} abc={forced_abc}"
            );
        }

        let trailing_comma = components(&mut heap);
        let trailing_layers = [trailing_comma, SourceMutPointer::null()];
        let before = values(&heap, trailing_comma);
        abc = 0;
        assert_eq!(
            parse(
                &mut heap,
                "o(1,2,)",
                TAUT_NON as i32,
                &trailing_layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(1)
        );
        assert_eq!(
            values(&heap, trailing_comma),
            vec![before[1], before[0], before[2]]
        );

        let duplicate = components(&mut heap);
        let duplicate_layers = [duplicate, SourceMutPointer::null()];
        let before = values(&heap, duplicate);
        abc = 0;
        assert_eq!(
            parse(
                &mut heap,
                "o(1,1)",
                TAUT_NON as i32,
                &duplicate_layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(1)
        );
        assert_eq!(values(&heap, duplicate), before);

        let partial = components(&mut heap);
        let partial_layers = [partial, SourceMutPointer::null()];
        let before = values(&heap, partial);
        abc = 0;
        assert_eq!(
            parse(
                &mut heap,
                "o(1,2x)",
                TAUT_NON as i32,
                &partial_layers,
                &counts,
                fixed_state,
                &mut abc,
            ),
            Ok(RI_ERR_SYNTAX)
        );
        assert_eq!(
            values(&heap, partial),
            vec![before[1], before[1], before[2]]
        );
    }

    #[test]
    fn source_port__ichiread__parsesegmentisoexchgh__line_5541() {
        use crate::source_types::{
            REM_PROTONS, local_ichiread::tagInChI_STATE_IST_MOBILE_H_ISO_EXCH_H,
        };

        fn parse(
            heap: &mut SourceHeap,
            text: &str,
            mobile: i32,
            state: u32,
            abc: &mut i32,
            protons: &mut [REM_PROTONS; TAUT_NUM as usize],
        ) -> Result<i32, SourceHeapError> {
            let input = c_string(heap, text);
            ParseSegmentIsoExchgH(heap, input, mobile, protons, &[0; 2], state, abc)
        }

        let state = tagInChI_STATE_IST_MOBILE_H_ISO_EXCH_H as u32;
        let mut heap = SourceHeap::default();
        let mut protons = std::array::from_fn(|_| REM_PROTONS::default());
        let mut abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "x3t",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(0)
        );
        assert_eq!(abc, -1);
        assert_eq!(
            parse(
                &mut heap,
                "h3t",
                TAUT_NON as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(RI_ERR_PROGR)
        );
        assert_eq!(
            parse(
                &mut heap,
                "h3t",
                TAUT_YES as i32,
                u32::MAX,
                &mut abc,
                &mut protons
            ),
            Ok(RI_ERR_PROGR)
        );
        assert_eq!(
            parse(
                &mut heap,
                "h3t;",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(RI_ERR_SYNTAX)
        );

        abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "h3t2d1h",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(1)
        );
        assert_eq!(abc, 1);
        assert_eq!(protons[TAUT_YES as usize].nNumRemovedIsotopicH, [1, 2, 3]);

        protons[TAUT_YES as usize].nNumRemovedIsotopicH = [0; 3];
        abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "h1h2d",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(RI_ERR_SYNTAX)
        );
        assert_eq!(protons[TAUT_YES as usize].nNumRemovedIsotopicH, [1, 0, 0]);
        for malformed in ["h0t", "h2", "h32768t", "h-1t"] {
            protons[TAUT_YES as usize].nNumRemovedIsotopicH = [0; 3];
            abc = 1;
            assert_eq!(
                parse(
                    &mut heap,
                    malformed,
                    TAUT_YES as i32,
                    state,
                    &mut abc,
                    &mut protons
                ),
                Ok(RI_ERR_SYNTAX),
                "{malformed}"
            );
        }

        protons[TAUT_YES as usize].nNumRemovedIsotopicH = [0; 3];
        abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "hT2D3H4",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(1)
        );
        assert_eq!(abc, 0);
        assert_eq!(protons[TAUT_YES as usize].nNumRemovedIsotopicH, [4, 3, 2]);
        assert_eq!(
            parse(
                &mut heap,
                "hT65535",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(1)
        );
        assert_eq!(protons[TAUT_YES as usize].nNumRemovedIsotopicH[2], -1);
        assert_eq!(
            parse(
                &mut heap,
                "hDT",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(RI_ERR_SYNTAX)
        );

        abc = -1;
        assert_eq!(
            parse(
                &mut heap,
                "h",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(1)
        );
        assert_eq!(abc, -1);
        abc = 0;
        assert_eq!(
            parse(
                &mut heap,
                "h1t",
                TAUT_YES as i32,
                state,
                &mut abc,
                &mut protons
            ),
            Ok(RI_ERR_SYNTAX)
        );
    }

