    #[test]
    fn source_port__ichiread__detectandexposepolymerinternals__line_11629() {
        fn input_stream(heap: &mut SourceHeap, text: &str) -> INCHI_IOSTREAM {
            INCHI_IOSTREAM {
                type_: INCHI_IOS_TYPE_STRING as i32,
                s: INCHI_IOS_STRING {
                    pStr: c_string(heap, text).as_mut(),
                    nAllocatedLength: i32::try_from(text.len() + 1).unwrap(),
                    nUsedLength: i32::try_from(text.len()).unwrap(),
                    nPtr: 0,
                },
                ..INCHI_IOSTREAM::default()
            }
        }

        for unchanged in [
            "not an InChI",
            "prefix InChI=1/C",
            "InChI=1/C/zplain",
            "InChI=1/C/z(open",
        ] {
            let mut heap = SourceHeap::default();
            let mut stream = input_stream(&mut heap, unchanged);
            assert_eq!(
                DetectAndExposePolymerInternals(&mut heap, &mut stream),
                Ok(0),
                "{unchanged}"
            );
            assert_eq!(log_text(&heap, &stream), unchanged, "{unchanged}");
            assert_eq!(heap.live_allocation_count(), 1, "{unchanged}");
        }

        let mut leading_heap = SourceHeap::default();
        let mut leading = input_stream(&mut leading_heap, " InChI=1/C/z()");
        assert_eq!(
            DetectAndExposePolymerInternals(&mut leading_heap, &mut leading),
            Ok(0)
        );
        assert_eq!(
            log_text(&leading_heap, &leading),
            " InChI=1/C.2Zz/z(2,3-)\n"
        );

        let mut heap = SourceHeap::default();
        let mut stream = input_stream(&mut heap, "InChI=1/C2H6/z(1,2)");
        heap.trace_source_allocations();
        assert_eq!(
            DetectAndExposePolymerInternals(&mut heap, &mut stream),
            Ok(0)
        );
        assert_eq!(log_text(&heap, &stream), "InChI=1/C2H6.2Zz/z(3,4-1,2)\n");
        assert_eq!(
            stream.s.nUsedLength as usize,
            log_text(&heap, &stream).len()
        );
        assert!(stream.s.nAllocatedLength > stream.s.nUsedLength);
        assert_eq!(heap.source_allocation_calls(), 5);
        assert_eq!(heap.live_allocation_count(), 1);

        let mut tail_heap = SourceHeap::default();
        let mut tail = input_stream(
            &mut tail_heap,
            "InChI=1/CH4/z()\tAuxInfo=1/0/N:1 InChIKey=ABC",
        );
        assert_eq!(
            DetectAndExposePolymerInternals(&mut tail_heap, &mut tail),
            Ok(0)
        );
        assert_eq!(
            log_text(&tail_heap, &tail),
            "InChI=1/CH4.2Zz/z(2,3-)\tAuxInfo=1/0/N:1 InChIKey=ABC\n"
        );
        assert_eq!(tail_heap.live_allocation_count(), 1);

        let mut reconnect_heap = SourceHeap::default();
        let mut reconnect = input_stream(&mut reconnect_heap, "InChI=1/C/z(1)/rC/z(2)");
        assert_eq!(
            DetectAndExposePolymerInternals(&mut reconnect_heap, &mut reconnect),
            Ok(0)
        );
        assert_eq!(
            log_text(&reconnect_heap, &reconnect),
            "InChI=1/C.2Zz/z(2,3-1)/rC.2Zz/z(2,3-2)\n"
        );
        assert_eq!(reconnect_heap.live_allocation_count(), 1);

        let mut layers_heap = SourceHeap::default();
        let mut layers = input_stream(&mut layers_heap, "InChI=1/C/z()/c1/m1/fabc/q1/p1/s1");
        assert_eq!(
            DetectAndExposePolymerInternals(&mut layers_heap, &mut layers),
            Ok(0)
        );
        assert_eq!(
            log_text(&layers_heap, &layers),
            "InChI=1/C.2Zz/z(2,3-)/c1;;/m1../fabc.2Zz/q1;;/p1/s1\n"
        );

        for (text, expected) in [
            ("InChI=1/c/z()", -1),
            ("InChI=1/Xx/z()", -1),
            ("InChI=1/C0/z()", -1),
            ("InChI=1/C32767/z()", RI_ERR_SYNTAX),
            ("InChI=1/32767C/z()", RI_ERR_SYNTAX),
            ("InChI=1/C/z)", -3),
            ("InChI=1/C/z(())", -3),
        ] {
            let mut heap = SourceHeap::default();
            let mut stream = input_stream(&mut heap, text);
            assert_eq!(
                DetectAndExposePolymerInternals(&mut heap, &mut stream),
                Ok(expected),
                "{text}"
            );
            assert_eq!(log_text(&heap, &stream), text, "{text}");
            assert_eq!(heap.live_allocation_count(), 1, "{text}");
        }

        let mut maximum_heap = SourceHeap::default();
        let mut maximum = input_stream(&mut maximum_heap, "InChI=1/C32766/z()");
        assert_eq!(
            DetectAndExposePolymerInternals(&mut maximum_heap, &mut maximum),
            Ok(0)
        );
        assert_eq!(
            log_text(&maximum_heap, &maximum),
            "InChI=1/C32766.2Zz/z(32767,32768-)\n"
        );

        for (failure_ordinal, expected, keeps_input) in [
            (0_u64, 0, true),
            (1, -2, true),
            (2, -2, true),
            (3, -2, true),
            (4, 0, false),
        ] {
            let mut heap = SourceHeap::default();
            let input = "InChI=1/C/z()";
            let mut stream = input_stream(&mut heap, input);
            heap.fail_after_allocations(failure_ordinal);
            assert_eq!(
                DetectAndExposePolymerInternals(&mut heap, &mut stream),
                Ok(expected),
                "allocation ordinal {failure_ordinal}"
            );
            assert_eq!(
                heap.source_allocation_calls(),
                failure_ordinal + 1,
                "allocation ordinal {failure_ordinal}"
            );
            if keeps_input {
                assert_eq!(log_text(&heap, &stream), input);
                assert_eq!(heap.live_allocation_count(), 1);
            } else {
                assert!(stream.s.pStr.is_null());
                assert_eq!(stream.s.nAllocatedLength, 0);
                assert_eq!(stream.s.nUsedLength, 0);
                assert_eq!(heap.live_allocation_count(), 0);
            }
        }

        let mut tail_failure_heap = SourceHeap::default();
        let mut tail_failure =
            input_stream(&mut tail_failure_heap, "InChI=1/C/z()\tAuxInfo=1/0/N:1");
        tail_failure_heap.fail_after_allocations(1);
        assert_eq!(
            DetectAndExposePolymerInternals(&mut tail_failure_heap, &mut tail_failure),
            Ok(0)
        );
        assert_eq!(
            log_text(&tail_failure_heap, &tail_failure),
            "InChI=1/C/z()\tAuxInfo=1/0/N:1"
        );
        assert_eq!(tail_failure_heap.live_allocation_count(), 1);

        let mut reconnect_failure_heap = SourceHeap::default();
        let mut reconnect_failure =
            input_stream(&mut reconnect_failure_heap, "InChI=1/C/z()/rC/z()");
        reconnect_failure_heap.fail_after_allocations(3);
        assert_eq!(
            DetectAndExposePolymerInternals(&mut reconnect_failure_heap, &mut reconnect_failure,),
            Ok(-2)
        );
        assert_eq!(
            log_text(&reconnect_failure_heap, &reconnect_failure),
            "InChI=1/C/z()/rC/z()"
        );
        assert_eq!(reconnect_failure_heap.live_allocation_count(), 1);

        let mut malformed_heap = SourceHeap::default();
        let mut malformed = INCHI_IOSTREAM {
            type_: INCHI_IOS_TYPE_STRING as i32,
            s: INCHI_IOS_STRING {
                pStr: SourceMutPointer::null(),
                nAllocatedLength: 4,
                nUsedLength: 3,
                ..INCHI_IOS_STRING::default()
            },
            ..INCHI_IOSTREAM::default()
        };
        assert_eq!(
            DetectAndExposePolymerInternals(&mut malformed_heap, &mut malformed),
            Err(SourceHeapError::NullPointer)
        );
        assert_eq!(malformed_heap.live_allocation_count(), 0);
    }

    fn output_stream() -> INCHI_IOSTREAM {
        INCHI_IOSTREAM {
            type_: INCHI_IOS_TYPE_STRING as i32,
            ..INCHI_IOSTREAM::default()
        }
    }

    #[test]
    fn source_port__ichiread__insertions_sort_at_numb__line_10546() {
        let mut untouched = [3, 2, 1];
        for num in [i32::MIN, -1, 0, 1] {
            assert_eq!(insertions_sort_AT_NUMB(&mut untouched, num), Ok(0));
            assert_eq!(untouched, [3, 2, 1]);
        }

        let mut values: [AT_NUMB; 8] = [5, 1, 3, 3, 0, u16::MAX, u16::MIN, 2];
        assert_eq!(insertions_sort_AT_NUMB(&mut values, 8), Ok(16));
        assert_eq!(values, [u16::MIN, 0, 1, 2, 3, 3, 5, u16::MAX]);

        let mut ascending = [0, 1, 2, 3];
        assert_eq!(insertions_sort_AT_NUMB(&mut ascending, 4), Ok(0));
        assert_eq!(ascending, [0, 1, 2, 3]);

        let mut descending = [4, 3, 2, 1];
        assert_eq!(insertions_sort_AT_NUMB(&mut descending, 4), Ok(6));
        assert_eq!(descending, [1, 2, 3, 4]);

        let mut prefix = [4, 2, 3, 1, 99, 98];
        assert_eq!(insertions_sort_AT_NUMB(&mut prefix, 4), Ok(5));
        assert_eq!(prefix, [1, 2, 3, 4, 99, 98]);
        assert_eq!(
            insertions_sort_AT_NUMB(&mut prefix, 7),
            Err(SourceHeapError::PointerOutOfBounds)
        );
    }

